Section GD_1.
  Context {RL : Reloc}.
Definition low_frame (sp0 : Z) (m m' : word -> option byte) : Prop :=
  exists rs, frame_mod m m' rs /\ (forall x : word, sp0 - 2768 <= bv_unsigned x -> outside x rs).
End GD_1.

